	static boolean isDirectionChange(Vec3d previous, Vec3d next) {
		double a = previous.lengthSquared();
		double b = next.lengthSquared();
		if (a < 1e-12 || b < 1e-12) {
			return false;
		}
		double dot = previous.dotProduct(next) / Math.sqrt(a * b);
		return dot < 1.0 - 1e-4;
	}

